  --color-foreground: var(--foreground);
  --color-border: var(--border);
  --color-background: var(--background);
  --color-muted-foreground: var(--muted-foreground);
  --color-surface: var(--surface);
  --color-clr-0: var(--clr-0);
  --color-clr-1: var(--clr-1);
  --color-color-001: var(--color-001);
  --color-primary: var(--primary);
  --color-clr-2: var(--clr-2);
  --color-clr-3: var(--clr-3);
  --color-clr-4: var(--clr-4);
  --color-clr-5: var(--clr-5);
  --color-clr-6: var(--clr-6);
}

/* Design tokens (values). */
:root {
  --background: rgb(255, 255, 255);
  --foreground: rgb(0, 0, 0);
  --primary: rgb(6, 13, 170);
  --border: rgb(25, 24, 23);
  --muted-foreground: rgb(85, 85, 85);
